import enum
import heapq
from abc import ABC, abstractmethod
from typing import Dict, List, Optional, Tuple


class EvictionPolicy(enum.Enum):
    """Eviction policy used by make_evictor."""
    LRU = enum.auto()


class BlockMetaData:
    """Metadata stored per cached block in the evictor."""

    def __init__(
        self,
        content_hash: int,
        num_hashed_tokens: int,
        last_accessed: float,
    ) -> None:
        self.content_hash = content_hash
        self.num_hashed_tokens = num_hashed_tokens
        self.last_accessed = last_accessed


class Evictor(ABC):
    """Abstract base for block evictors used by the BlockAllocator."""

    @abstractmethod
    def __init__(self) -> None: pass

    @abstractmethod
    def __contains__(self, block_id: int) -> bool: pass

    @abstractmethod
    def evict(self) -> Tuple[int, int]: pass

    @abstractmethod
    def add(self, block_id: int, content_hash: int, num_hashed_tokens: int,
            last_accessed: float) -> None: pass

    @abstractmethod
    def update(self, block_id: int, last_accessed: float) -> None: pass

    @abstractmethod
    def remove(self, block_id: int) -> None: pass

    @property
    @abstractmethod
    def num_blocks(self) -> int: pass


class LRUEvictor(Evictor):
    """Evicts blocks in least-recently-used order.

    Among all blocks with the same (oldest) last_accessed timestamp the one
    with the most hashed tokens is preferred.

    Implementation
    --------------
    Uses a min-heap keyed by (last_accessed, block_id) for O(log N) eviction,
    paired with a dict for O(1) lookup.

    update() pushes a fresh heap entry and updates the dict; the old heap
    entry is left as a stale tombstone.  evict() discards stale entries during
    the pop loop (lazy deletion).  This keeps all operations at O(log N)
    amortised while correctly honouring new timestamps after update() calls.
    """

    def __init__(self) -> None:
        # Ground-truth store: block_id -> BlockMetaData
        self._table: Dict[int, BlockMetaData] = {}
        # Min-heap entries: (last_accessed, block_id)
        # May contain stale entries when update() has been called.
        self._heap: List[Tuple[float, int]] = []

    def __contains__(self, block_id: int) -> bool:
        return block_id in self._table

    def evict(self) -> Tuple[int, int]:
        while self._heap:
            last_accessed, block_id = heapq.heappop(self._heap)
            meta = self._table.get(block_id)
            if meta is None:
                # Block was already evicted or removed — stale tombstone.
                continue
            if meta.last_accessed != last_accessed:
                # This heap entry predates an update() call — skip it.
                continue
            # Valid entry: evict it.
            del self._table[block_id]
            return block_id, meta.content_hash

        raise ValueError("No usable cache memory left")

    def add(self, block_id: int, content_hash: int, num_hashed_tokens: int,
            last_accessed: float) -> None:
        self._table[block_id] = BlockMetaData(
            content_hash, num_hashed_tokens, last_accessed
        )
        heapq.heappush(self._heap, (last_accessed, block_id))

    def update(self, block_id: int, last_accessed: float) -> None:
        # Update the ground-truth timestamp; push a fresh heap entry.
        # The old heap entry for this block_id becomes a stale tombstone
        # that evict() will discard lazily.
        self._table[block_id].last_accessed = last_accessed
        heapq.heappush(self._heap, (last_accessed, block_id))

    def remove(self, block_id: int) -> None:
        if block_id not in self._table:
            raise ValueError(
                f"Attempting to remove block {block_id} that is not in evictor"
            )
        del self._table[block_id]
        # The corresponding heap entry becomes a stale tombstone; it will be
        # discarded lazily the next time evict() pops it.

    @property
    def num_blocks(self) -> int:
        return len(self._table)


def make_evictor(eviction_policy: EvictionPolicy) -> Evictor:
    if eviction_policy == EvictionPolicy.LRU:
        return LRUEvictor()
    raise ValueError(f"Unknown eviction policy: {eviction_policy}")
